def emit(id,a):
 p=slug(a['project']);path=a.get('path','/health');module=a.get('app_module','app.main');framework=a.get('framework','fastapi');base=a.get('base_url','http://127.0.0.1:3000')
 if id=='test.gen.e2e':
  code='const assert=require("node:assert/strict");const {spawn}=require("node:child_process");const {chromium}=require("playwright");\n(async()=>{const app=spawn("python3",["-m","uvicorn",'+json.dumps(module+':app')+',"--host","127.0.0.1","--port","3000"],{stdio:"ignore",env:{...process.env,APP_DATABASE:"/tmp/qa.sqlite",APP_DB_PATH:"/tmp/qa.sqlite",DATABASE_URL:"sqlite:////tmp/qa.sqlite"}});let browser;try{let ready=false;for(let i=0;i<100;i++){try{if((await fetch('+json.dumps(base+path)+')).ok){ready=true;break;}}catch{}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,"app_not_ready");browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:["--no-sandbox","--disable-gpu","--disable-dev-shm-usage"]});for(const viewport of [{width:1280,height:900},{width:390,height:844}]){const page=await browser.newPage({viewport});const errors=[];page.on("pageerror",e=>errors.push(e.message));await page.goto('+json.dumps(base)+');assert.equal(await page.locator("body").isVisible(),true);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(errors.length,0);await page.close();}console.log("browser_checks_passed");}finally{if(browser)await browser.close();app.kill("SIGTERM");}})().catch(e=>{console.error(e.message);process.exitCode=1;});\n'
  name='tests/generated-browser.cjs';cmd='node tests/generated-browser.cjs';requires=['Install/pin playwright and a software Chromium runtime. Set the actual app_module and health path. The generated starter targets FastAPI; adapt the spawn command for a Node app.']
