 return {'data':{'test_file':p+'/'+name,'suggested_command':cmd,'executed':False,'requires_configuration':requires},'writes':[(p+'/'+name,code)],'limitations':['Generated test code only. No test passed/coverage/browser score is asserted. Add business-specific assertions from the actual specification.']}
